 });
+
+test("concurrent addItem calls assign distinct ids", async () => {
+  const [a, b] = await Promise.all([
+    addItem({ name: "salt", qty: 1, unit: "box" }),
+    addItem({ name: "sugar", qty: 1, unit: "bag" }),
+  ]);
+  assert.notEqual(a.id, b.id);
+  assert.deepEqual([a.id, b.id].sort((x, y) => x - y), [6, 7]);
+  assert.equal((await fetchItems()).length, 7);
+});
